-- Durable per-learner storage for lessons generated by /api/cortex/generate-lesson.
-- Keep IDs as text because the generator issues lesson_<timestamp>_<random> identifiers.
create table if not exists public.generated_lessons (
  id text primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  topic text not null check (char_length(btrim(topic)) > 0),
  subject_id uuid references public.subjects(id) on delete set null,
  title text not null check (char_length(btrim(title)) > 0),
  content jsonb not null,
  metadata jsonb not null default '{}'::jsonb,
  format text not null default 'explanation'
    check (format in ('explanation', 'practice', 'quiz')),
  validation_score integer not null check (validation_score between 0 and 100),
  created_at timestamptz not null default now()
);

create index if not exists generated_lessons_user_created_idx
  on public.generated_lessons (user_id, created_at desc);

create index if not exists generated_lessons_user_subject_idx
  on public.generated_lessons (user_id, subject_id);

alter table public.generated_lessons enable row level security;

drop policy if exists generated_lessons_select_own on public.generated_lessons;
create policy generated_lessons_select_own
  on public.generated_lessons for select to authenticated
  using ((select auth.uid()) = user_id);

drop policy if exists generated_lessons_insert_own on public.generated_lessons;
create policy generated_lessons_insert_own
  on public.generated_lessons for insert to authenticated
  with check ((select auth.uid()) = user_id);

drop policy if exists generated_lessons_delete_own on public.generated_lessons;
create policy generated_lessons_delete_own
  on public.generated_lessons for delete to authenticated
  using ((select auth.uid()) = user_id);

revoke all on public.generated_lessons from anon;
grant select, insert, delete on public.generated_lessons to authenticated;
